```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("trojkaty.txt");
    int n;
    plik >> n;
    int cntRam = 0, cntP = 0, cntRozn = 0;
    cout << fixed << setprecision(2);
    double eps = 0.01;
    for (int t = 0; t < n; t++) {
        int x1, y1, x2, y2, x3, y3;
        plik >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
        double s[3];
        s[0] = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
        s[1] = sqrt(pow(x3 - x2, 2) + pow(y3 - y2, 2));
        s[2] = sqrt(pow(x1 - x3, 2) + pow(y1 - y3, 2));
        sort(s, s + 3);
        double pole = abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0;
        string typ;
        if (fabs(s[0] - s[1]) < eps || fabs(s[1] - s[2]) < eps) {
            typ = "rownoramienny";
            cntRam++;
        } else if (fabs(s[0] * s[0] + s[1] * s[1] - s[2] * s[2]) < eps) {
            typ = "prostokatny";
            cntP++;
        } else {
            typ = "roznoboczny";
            cntRozn++;
        }
        cout << "Trojkat " << t + 1 << ": boki (" << s[0] << ", " << s[1] << ", " << s[2]
             << "), pole = " << pole << " -> " << typ << endl;
    }
    cout << endl << "Podsumowanie:" << endl;
    cout << "  rownoramienny: " << cntRam << endl;
    cout << "  prostokatny: " << cntP << endl;
    cout << "  roznoboczny: " << cntRozn << endl;
    return 0;
}
```

**Wyjasnienie**: Dlugosci bokow obliczamy z odleglosci euklidesowej, sortujemy rosnaco, potem klasyfikujemy. Uwaga: trojkat rownoboczny o calkowitych wspolrzednych nie istnieje, wiec pomijamy ten typ.

Weryfikacja:
- T1 (0,0)(6,0)(3,4): boki 6, sqrt(9+16)=5, sqrt(9+16)=5. Sorted: (5.00, 5.00, 6.00). |5-5|<eps -> rownoramienny. Pole=|0+24+0|/2=12.00
- T2 (0,0)(4,0)(2,3): boki 4, sqrt(4+9)=3.61, sqrt(4+9)=3.61. Sorted: (3.61, 3.61, 4.00). |3.61-3.61|<eps -> rownoramienny. Pole=|0+12+0|/2=6.00
- T3 (0,0)(3,0)(0,4): boki 3, sqrt(9+16)=5, 4. Sorted: (3.00, 4.00, 5.00). Boki rozne. 9+16=25=25 -> prostokatny. Pole=|0+12+0|/2=6.00
- T4 (0,0)(7,0)(2,5): boki 7, sqrt(25+25)=7.07, sqrt(4+25)=5.39. Sorted: (5.39, 7.00, 7.07). |7.00-7.07|=0.07>eps -> nie rownoram. |29+49-50|=28>>eps -> nie prostokatny. Roznoboczny. Pole=|0+35+0|/2=17.50
- T5 (0,0)(10,0)(3,2): boki 10, sqrt(49+4)=7.28, sqrt(9+4)=3.61. Sorted: (3.61, 7.28, 10.00). Boki rozne. |13+53-100|=34>>eps -> nie prostokatny. Roznoboczny. Pole=|0+20+0|/2=10.00
